export function verifyManifest(root, manifest) {
  validateManifest(manifest);
  validateRoot(root);
  const report = {ok:false,unchanged:[],changed:[],missing:[],unsafe:[]};
  for (const entry of manifest.files) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing') report.missing.push(entry.path);
    else if (current.kind === 'unsafe') report.unsafe.push(entry.path);
    else {
      const reasons = [];
      if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
      if (current.mode !== entry.mode) reasons.push('mode');
      if (reasons.length) report.changed.push({path:entry.path,reasons});
      else report.unchanged.push(entry.path);
    }
  }
  report.unchanged.sort(); report.changed.sort((a,b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
  report.missing.sort(); report.unsafe.sort();
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}
function cli() {
  const [command, root, ...rest] = process.argv.slice(2);
  if (command === 'create' && typeof root === 'string') {
    if (!rest.length && process.argv.length < 4) throw Error('missing arguments');
    process.stdout.write(`${JSON.stringify(createManifest(root, rest))}\n`); return 0;
  }
  if (command === 'verify' && typeof root === 'string' && rest.length === 1) {
    const manifest = JSON.parse(fs.readFileSync(rest[0], 'utf8'));
    const report = verifyManifest(root, manifest);
    process.stdout.write(`${JSON.stringify(report)}\n`); return report.ok ? 0 : 1;
  }
