import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {createManifest, verifyManifest} from '../snapshot.js';

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-retained-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function digest(value) { return crypto.createHash('sha256').update(value).digest('hex'); }
function entry(name, value = 'x', mode = 0o644) { return {path:name,sha256:digest(value),size:Buffer.byteLength(value),mode}; }
function run(...args) { return spawnSync(process.execPath, ['snapshot.js', ...args], {encoding:'utf8'}); }

test('verifier has exact deterministic report ordering and does not mutate inputs', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'z'), 'same');
  fs.writeFileSync(path.join(root, 'a'), 'old');
  fs.writeFileSync(path.join(root, 'm'), 'mode'); fs.chmodSync(path.join(root, 'm'), 0o600);
  const manifest = {version:1, ignored:true, files:[entry('z','same'), entry('a','other'), entry('gone'), entry('m','mode',0o644)]};
  const before = JSON.stringify(manifest);
  assert.deepEqual(verifyManifest(root, manifest), {ok:false, unchanged:['z'], changed:[{path:'a',reasons:['content']},{path:'m',reasons:['mode']}], missing:['gone'], unsafe:[]});
  assert.equal(JSON.stringify(manifest), before);
  assert.deepEqual(verifyManifest(root, {version:1,files:[]}), {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]});
});

test('content reasons cover equal-size hash changes and combined mode drift', t => {
  const root = fixture(t); fs.writeFileSync(path.join(root, 'f'), 'ab');
  const manifest = createManifest(root, ['f']);
  const bytes = fs.readFileSync(path.join(root, 'f'));
  fs.writeFileSync(path.join(root, 'f'), 'cd'); fs.chmodSync(path.join(root, 'f'), 0o600);
  assert.deepEqual(verifyManifest(root, manifest).changed, [{path:'f',reasons:['content','mode']}]);
  assert.deepEqual(fs.readFileSync(path.join(root, 'f')), Buffer.from('cd'));
  assert.notDeepEqual(bytes, fs.readFileSync(path.join(root, 'f')));
});

test('missing and unsafe components are classified without following symlinks', t => {
  const root = fixture(t);
  fs.mkdirSync(path.join(root, 'dir')); fs.writeFileSync(path.join(root, 'dir', 'file'), 'x');
  const manifest = {version:1,files:[entry('missing/x'),entry('dir/missing/x'),entry('link/x'),entry('dir/link'),entry('dir/file/x'),entry('dir')]};
  fs.symlinkSync(path.join(root, 'dir'), path.join(root, 'link'));
  fs.symlinkSync('nowhere', path.join(root, 'dir', 'link'));
  assert.deepEqual(verifyManifest(root, manifest), {ok:false,unchanged:[],changed:[],missing:['missing/x','dir/missing/x'],unsafe:['dir','dir/file/x','dir/link','link/x']});
});

test('validation rejects roots and malformed manifests before inspection', t => {
  const root = fixture(t); fs.writeFileSync(path.join(root, 'ok'), 'x');
  const bad = [null, [], {}, {version:2,files:[]}, {version:1,files:{}}, {version:1,files:[null]}, {version:1,files:[{path:'a',sha256:'A'.repeat(64),size:0,mode:0}]}, {version:1,files:[{path:'a',sha256:'0'.repeat(64),size:-1,mode:0}]}, {version:1,files:[{path:'a',sha256:'0'.repeat(64),size:0,mode:512}]}, {version:1,files:[entry('a'),entry('a')]}, {version:1,files:[entry('../a')]}, {version:1,files:[entry('a//b')]}, {version:1,files:[entry('a\\b')]}, {version:1,files:[entry('/a')]}];
  for (const manifest of bad) assert.throws(() => verifyManifest(root, manifest));
  const link = `${root}-link`; fs.symlinkSync(root, link); t.after(() => fs.rmSync(link));
  assert.throws(() => verifyManifest(link, {version:1,files:[]}));
  assert.throws(() => verifyManifest(path.join(root, 'ok'), {version:1,files:[]}));
});

test('unusual valid names and unselected files are supported', t => {
  const root = fixture(t), name = ' space\tnewline\nユニコード ';
  fs.writeFileSync(path.join(root, name), 'yes'); fs.writeFileSync(path.join(root, 'ignored'), 'no');
  const manifest = createManifest(root, [name]);
  fs.writeFileSync(path.join(root, 'ignored'), 'changed');
  assert.deepEqual(verifyManifest(root, manifest), {ok:true,unchanged:[name],changed:[],missing:[],unsafe:[]});
});

test('CLI has guarded output and status behavior', t => {
  const root = fixture(t), manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(path.join(root, 'a'), 'abc');
  let result = run('create', root);
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.deepEqual(JSON.parse(result.stdout), {version:1,files:[]});
  result = run('create', root, 'a');
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); const manifest = JSON.parse(result.stdout); assert.equal(manifest.files[0].path, 'a');
  fs.writeFileSync(manifestFile, JSON.stringify(manifest));
  result = run('verify', root, manifestFile);
  assert.equal(result.status, 0); assert.equal(result.stderr, ''); assert.equal(JSON.parse(result.stdout).ok, true);
  fs.writeFileSync(path.join(root, 'a'), 'def'); result = run('verify', root, manifestFile);
  assert.equal(result.status, 1); assert.equal(result.stderr, ''); assert.equal(JSON.parse(result.stdout).ok, false);
  for (const args of [['wat'], ['verify',root], ['verify',root,path.join(root,'none')], ['verify',root,manifestFile,'extra']]) {
    result = run(...args); assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  }
  fs.writeFileSync(manifestFile, '{'); result = run('verify',root,manifestFile);
  assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  result = spawnSync(process.execPath, ['-e', "import('./snapshot.js').then(() => process.stdout.write('imported'))"], {encoding:'utf8'});
  assert.equal(result.status, 0); assert.equal(result.stdout, 'imported'); assert.equal(result.stderr, '');
});

